"use client";

import React, { useState } from "react";
import { 
  Folder, FileText, UploadCloud, Search, MoreVertical, 
  Download, Trash2, Share2, ShieldCheck, AlertCircle, 
  ChevronRight, ChevronDown, CheckCircle2, History 
} from "lucide-react";
import Badge from "@/components/ui/badge/Badge";

/* --- Types & Sample Data --- */
type DocStatus = "Verified" | "Expiring" | "Action Required" | "None";

interface DocFile {
  id: string;
  name: string;
  size: string;
  uploaded: string;
  status: DocStatus;
  ocrScore: number;
}

interface FolderData {
  id: string;
  name: string;
  hasAlert?: boolean;
  files: DocFile[];
}

const initialFolders: FolderData[] = [
  {
    id: "1",
    name: "Identity & KYC",
    hasAlert: true,
    files: [
      { id: "f1", name: "Passport_Scan.pdf", size: "2.4 MB", uploaded: "12 Jan 2026", status: "Expiring", ocrScore: 98 },
      { id: "f2", name: "Aadhar_Verified.pdf", size: "1.1 MB", uploaded: "01 Jan 2026", status: "Verified", ocrScore: 100 },
    ]
  },
  {
    id: "2",
    name: "Employment & Contracts",
    files: [
      { id: "f3", name: "Offer_Letter.pdf", size: "900 KB", uploaded: "20 Dec 2025", status: "Verified", ocrScore: 100 },
      { id: "f4", name: "Service_Agreement.pdf", size: "1.5 MB", uploaded: "21 Dec 2025", status: "None", ocrScore: 85 },
    ]
  }
];

export default function EliteExplorer() {
  const [folders, setFolders] = useState(initialFolders);
  const [selectedFolder, setSelectedFolder] = useState<FolderData>(initialFolders[0]);
  const [search, setSearch] = useState("");

  return (
    <div className="p-6 lg:p-8 space-y-6 bg-[#F8F9FB] dark:bg-[#06080F] min-h-screen">
      
      {/* 1. TOP STATS BAR (Integrated into the old view) */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-4">
        <div className="bg-white dark:bg-gray-900 p-5 rounded-2xl border border-gray-100 dark:border-gray-800 flex items-center gap-4">
          <div className="p-3 bg-brand-50 text-brand-600 rounded-xl"><ShieldCheck size={20}/></div>
          <div>
            <p className="text-[10px] font-black uppercase text-gray-400">Compliance</p>
            <p className="text-lg font-black tracking-tight">92% Secure</p>
          </div>
        </div>
        {/* ... add more stats if needed ... */}
      </div>

      <div className="grid grid-cols-12 gap-6 items-start">
        
        {/* 2. SIDEBAR FOLDER TREE (The "Old" Logic but Premium) */}
        <div className="col-span-12 lg:col-span-3 bg-white dark:bg-gray-900 rounded-[2rem] p-5 border border-gray-100 dark:border-gray-800 h-[650px] flex flex-col shadow-sm">
          <div className="flex items-center justify-between mb-6 px-2">
            <h3 className="font-black text-sm uppercase tracking-widest text-gray-500">Archives</h3>
            <button className="p-2 hover:bg-gray-50 rounded-lg"><UploadCloud size={16}/></button>
          </div>

          <div className="space-y-1 flex-1 overflow-y-auto no-scrollbar">
            {folders.map(folder => (
              <button
                key={folder.id}
                onClick={() => setSelectedFolder(folder)}
                className={`w-full flex items-center justify-between px-4 py-3 rounded-2xl transition-all ${
                  selectedFolder.id === folder.id 
                  ? "bg-brand-50 text-brand-600 dark:bg-brand-500/10" 
                  : "text-gray-500 hover:bg-gray-50 dark:hover:bg-gray-800"
                }`}
              >
                <div className="flex items-center gap-3">
                  <Folder size={18} className={selectedFolder.id === folder.id ? "text-brand-600" : "text-gray-400"} />
                  <span className="text-sm font-bold">{folder.name}</span>
                </div>
                {folder.hasAlert && <div className="w-2 h-2 rounded-full bg-red-500 shadow-[0_0_8px_rgba(239,68,68,0.6)]" />}
              </button>
            ))}
          </div>

          <div className="mt-auto p-4 bg-gray-50 dark:bg-gray-800 rounded-2xl border border-gray-100 dark:border-gray-700">
             <p className="text-[10px] font-bold text-gray-400 uppercase mb-2 text-center tracking-widest">Storage: 42% Used</p>
             <div className="w-full h-1.5 bg-gray-200 dark:bg-gray-700 rounded-full overflow-hidden">
                <div className="h-full bg-brand-500 w-[42%]" />
             </div>
          </div>
        </div>

        {/* 3. THE SMART FILE AREA */}
        <div className="col-span-12 lg:col-span-9 space-y-4">
          {/* SEARCH & FILTERS */}
          <div className="bg-white dark:bg-gray-900 p-4 rounded-2xl flex items-center gap-4 border border-gray-100 dark:border-gray-800 shadow-sm">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-2.5 text-gray-400" size={16} />
              <input 
                placeholder={`Search in ${selectedFolder.name}...`} 
                className="w-full pl-10 pr-4 py-2 bg-gray-50 dark:bg-gray-800 border-none rounded-xl text-sm outline-none focus:ring-1 focus:ring-brand-500" 
              />
            </div>
            <button className="flex items-center gap-2 bg-brand-600 text-white px-5 py-2 rounded-xl text-sm font-bold shadow-lg shadow-brand-500/20">
              <UploadCloud size={16} /> Upload New
            </button>
          </div>

          {/* FILE LIST VIEW */}
          <div className="bg-white dark:bg-gray-900 rounded-[2.5rem] border border-gray-100 dark:border-gray-800 overflow-hidden shadow-sm">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-gray-50/50 dark:bg-gray-800/50 text-[10px] uppercase font-black tracking-[0.1em] text-gray-400">
                  <th className="px-8 py-4">Document / Metadata</th>
                  <th className="px-8 py-4 text-center">OCR Trust</th>
                  <th className="px-8 py-4">Status</th>
                  <th className="px-8 py-4 text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50 dark:divide-gray-800">
                {selectedFolder.files.map((file) => (
                  <tr key={file.id} className="group hover:bg-gray-50/50 transition-colors cursor-pointer">
                    <td className="px-8 py-5">
                      <div className="flex items-center gap-4">
                        <div className="p-3 bg-gray-100 dark:bg-gray-800 rounded-xl text-gray-400 group-hover:text-brand-600 transition-colors">
                          <FileText size={20} />
                        </div>
                        <div>
                          <p className="text-sm font-black text-gray-900 dark:text-white">{file.name}</p>
                          <p className="text-[10px] font-bold text-gray-400 uppercase">{file.size} • {file.uploaded}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-8 py-5">
                      <div className="flex flex-col items-center gap-1">
                        <span className="text-[10px] font-black text-emerald-500 italic">{file.ocrScore}%</span>
                        <div className="w-12 h-1 bg-gray-100 dark:bg-gray-800 rounded-full overflow-hidden">
                          <div className="h-full bg-emerald-500" style={{ width: `${file.ocrScore}%` }} />
                        </div>
                      </div>
                    </td>
                    <td className="px-8 py-5">
                      <StatusBadge status={file.status} />
                    </td>
                    <td className="px-8 py-5">
                      <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                         <ActionBtn icon={<Download size={16}/>} />
                         <ActionBtn icon={<History size={16}/>} />
                         <ActionBtn icon={<Share2 size={16}/>} />
                         <ActionBtn icon={<Trash2 size={16}/>} variant="danger" />
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}

const ActionBtn = ({ icon, variant = "default" }: any) => (
  <button className={`p-2 rounded-lg transition-colors ${
    variant === "danger" ? "hover:bg-red-50 text-gray-400 hover:text-red-500" : "hover:bg-brand-50 text-gray-400 hover:text-brand-600"
  }`}>
    {icon}
  </button>
);

const StatusBadge = ({ status }: { status: DocStatus }) => {
  if (status === "None") return <span className="text-gray-300 text-[10px] font-bold">UNVERIFIED</span>;
  const colors: any = {
    Verified: "bg-emerald-50 text-emerald-600",
    Expiring: "bg-amber-50 text-amber-600 animate-pulse",
    "Action Required": "bg-red-50 text-red-600",
  };
  return <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase ${colors[status]}`}>{status}</span>;
}